package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import java.util.*;
@RestController @RequestMapping("/api/stores/{storeId}") public class StoreDetailsController {
 private final StoreAccess access;private final StockBatchService locks;private final StoreMemberRepository members;private final WorkShiftRepository shifts;private final WorkSessionRepository sessions;
 public StoreDetailsController(StoreAccess access,StockBatchService locks,StoreMemberRepository members,WorkShiftRepository shifts,WorkSessionRepository sessions){this.access=access;this.locks=locks;this.members=members;this.shifts=shifts;this.sessions=sessions;}
 public record Info(String name,String type,String branch,String address,String addressDetail,String openTime,String closeTime,Double latitude,Double longitude,int radius,long revision){}
 public record Contact(String name,String phone){}
 private Info view(Store s){return new Info(s.getName(),s.getType(),s.getBranch(),s.getAddress(),s.getAddressDetail(),s.getOpenTime(),s.getCloseTime(),s.getLatitude(),s.getLongitude(),s.getAttendanceRadius(),s.getDetailRevision());}
 @GetMapping("/details") @Transactional(readOnly=true) public Info get(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){return view(access.requireMember(a,storeId));}
 @PutMapping("/details") @Transactional public Info put(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@RequestBody Info r){Store s=access.requireOwner(a,storeId);locks.lock(s);if(r.revision()!=s.getDetailRevision())throw new ApiException(HttpStatus.CONFLICT,"매장 정보가 변경됐어요. 다시 조회해주세요");if(r.name()==null||r.name().isBlank()||r.name().length()>50||r.type()==null||r.type().length()>20||r.branch()!=null&&r.branch().length()>50||r.address()==null||r.address().isBlank()||r.address().length()>250||r.addressDetail()!=null&&r.addressDetail().length()>250||r.openTime()==null||!r.openTime().matches("([01]\\d|2[0-3]):[0-5]\\d")||r.closeTime()==null||!r.closeTime().matches("([01]\\d|2[0-3]):[0-5]\\d|24:00")||r.radius()<0||r.radius()>1000||(r.latitude()==null)!=(r.longitude()==null)||r.latitude()!=null&&(!Double.isFinite(r.latitude())||Math.abs(r.latitude())>90||!Double.isFinite(r.longitude())||Math.abs(r.longitude())>180)||r.radius()>0&&r.latitude()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"매장 정보·영업시간·위치·반경을 확인해주세요 (반경 0은 위치 확인 사용 안 함)");s.details(r.name().trim(),r.type(),r.branch(),r.address().trim(),r.addressDetail(),r.openTime(),r.closeTime(),r.latitude(),r.longitude(),r.radius());return view(s);}
 private StoreMember employee(Account a,Long sid,Long mid){access.requireOwner(a,sid);return members.findById(mid).filter(m->m.getStore().getId().equals(sid)&&m.getRole()==Role.STAFF&&m.getStatus()==MemberStatus.APPROVED).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"소속 직원을 찾을 수 없어요"));}
 @GetMapping("/staff/{memberId}/contact") @Transactional(readOnly=true) public Contact contact(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable Long memberId){var m=employee(a,storeId,memberId);return new Contact(m.getDisplayName(),m.getContactPhone());}
 @PutMapping("/staff/{memberId}/contact") @Transactional public Contact contact(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId,@PathVariable Long memberId,@RequestBody Contact r){var m=employee(a,storeId,memberId);locks.lock(m.getStore());if(r.name()==null||r.name().isBlank()||r.name().length()>30||r.phone()!=null&&!r.phone().matches("[0-9+() -]{0,30}"))throw new ApiException(HttpStatus.BAD_REQUEST,"직원 이름·연락처를 확인해주세요");m.contact(r.name().trim(),r.phone()==null?null:r.phone().trim());return contact(a,storeId,memberId);}
 public record Scheduled(long memberId,String name,String start,String end,boolean working){}
 @GetMapping("/dashboard/scheduled") @Transactional(readOnly=true) public List<Scheduled> scheduled(@RequestAttribute(AuthInterceptor.ACCOUNT)Account a,@PathVariable Long storeId){var s=access.requireOwner(a,storeId);var active=sessions.findByStoreAndClockOutIsNullOrderByClockInAsc(s).stream().map(w->w.getAccount().getId()).collect(java.util.stream.Collectors.toSet());var day=java.time.LocalDate.now();return members.findByStoreAndStatusOrderByIdAsc(s,MemberStatus.APPROVED).stream().filter(m->m.getRole()==Role.STAFF).flatMap(m->shifts.findByMemberAndDay(m,day).stream().map(shift->new Scheduled(m.getId(),m.getDisplayName(),shift.getStartTime(),shift.getEndTime(),active.contains(m.getAccount().getId())))).toList();}
 public static double distance(double lat1,double lng1,double lat2,double lng2){double a=Math.pow(Math.sin(Math.toRadians(lat2-lat1)/2),2)+Math.cos(Math.toRadians(lat1))*Math.cos(Math.toRadians(lat2))*Math.pow(Math.sin(Math.toRadians(lng2-lng1)/2),2);return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(Math.max(0,1-a)));}
 public static void checkLocation(Store s,Dto.ClockInRequest r){if(s.getAttendanceRadius()==0)return;if(r.latitude()==null||r.longitude()==null||r.accuracy()==null||r.locationAt()==null||!Double.isFinite(r.latitude())||Math.abs(r.latitude())>90||!Double.isFinite(r.longitude())||Math.abs(r.longitude())>180||!Double.isFinite(r.accuracy())||r.accuracy()<0||r.accuracy()>Math.max(50,s.getAttendanceRadius())||(r.locationAt()<java.time.Instant.now().toEpochMilli()-120000||r.locationAt()>java.time.Instant.now().toEpochMilli()+120000))throw new ApiException(HttpStatus.BAD_REQUEST,"정확한 현재 위치를 확인한 뒤 다시 출근해주세요");if(distance(s.getLatitude(),s.getLongitude(),r.latitude(),r.longitude())>s.getAttendanceRadius())throw new ApiException(HttpStatus.BAD_REQUEST,"설정된 매장 반경 안에서 출근해주세요");}
}
